<script setup>
import { computed } from 'vue';

const props = defineProps({
  name: {
    type: String,
    default: 'Docker'
  },
  size: {
    type: [Number, String],
    default: 28
  }
});

// Unique ID per component instance to avoid SVG gradient ID collisions in DOM
const instanceId = Math.random().toString(36).substring(2, 8);

const normName = computed(() => {
  const n = (props.name || '').trim().toLowerCase();
  if (n.includes('vue')) return 'vue';
  if (n.includes('react')) return 'react';
  if (n.includes('next')) return 'next';
  if (n.includes('python') || n === 'py') return 'python';
  if (n.includes('spring')) return 'spring';
  if (n.includes('java')) return 'java';
  if (n.includes('node')) return 'node';
  if (n.includes('golang') || n === 'go') return 'go';
  if (n.includes('rust')) return 'rust';
  if (n.includes('k8s') || n.includes('kube') || n.includes('kubernetes')) return 'k8s';
  if (n.includes('redis')) return 'redis';
  if (n.includes('mysql')) return 'mysql';
  if (n.includes('postgres')) return 'postgres';
  if (n.includes('ai') || n.includes('llm') || n.includes('gpt')) return 'ai';
  if (n.includes('docker')) return 'docker';
  return 'docker';
});

const sizePx = computed(() => {
  if (typeof props.size === 'number') {
    return `${props.size}px`;
  }
  return props.size.endsWith('px') || props.size.endsWith('%') || props.size.endsWith('rem') ? props.size : `${props.size}px`;
});
</script>
